export const envelope = [48, 32, 48];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function terrainY(x, z) {
    let h = Math.round(api.heightAt(x, z));
    if (h < 0) {
      h = 0;
    }
    if (h > 4) {
      h = 4;
    }
    return h;
  }

  function groundPatch(x, z, block) {
    const gx = Math.round(x);
    const gz = Math.round(z);

    if (gx < 0 || gx >= W || gz < 0 || gz >= D) {
      return;
    }

    const g = terrainY(gx, gz);
    for (let y = 0; y <= g; y++) {
      put(
        gx,
        y,
        gz,
        y === g ? block : "minecraft:deepslate"
      );
    }
  }

  function addEllipsoid(cx, cy, cz, rx, ry, rz, chooser) {
    const x0 = Math.floor(cx - rx);
    const x1 = Math.ceil(cx + rx);
    const y0 = Math.floor(cy - ry);
    const y1 = Math.ceil(cy + ry);
    const z0 = Math.floor(cz - rz);
    const z1 = Math.ceil(cz + rz);

    for (let x = x0; x <= x1; x++) {
      for (let y = y0; y <= y1; y++) {
        for (let z = z0; z <= z1; z++) {
          const dx = (x - cx) / rx;
          const dy = (y - cy) / ry;
          const dz = (z - cz) / rz;

          if (dx * dx + dy * dy + dz * dz <= 1) {
            put(x, y, z, chooser(x, y, z));
          }
        }
      }
    }
  }

  function wetMaterial(x, y, z, phase) {
    const n = (x * 13 + y * 17 + z * 19 + phase * 23) % 47;

    if (n === 0 || n === 1) {
      return "minecraft:cyan_concrete";
    }
    if (n === 2 || n === 3 || n === 4) {
      return "minecraft:prismarine";
    }
    if (n === 5) {
      return "minecraft:prismarine_bricks";
    }
    if (n === 6) {
      return "minecraft:blue_concrete";
    }
    return "minecraft:dark_prismarine";
  }

  function jawMaterial(x, y, z) {
    const n = (x * 11 + y * 7 + z * 5) % 13;

    if (n === 0 || n === 1) {
      return "minecraft:prismarine";
    }
    return "minecraft:dark_prismarine";
  }

  function foamMaterial(x, z) {
    const n = (x * 7 + z * 13) % 7;

    if (n === 0) {
      return "minecraft:light_blue_concrete";
    }
    if (n === 1 || n === 2) {
      return "minecraft:calcite";
    }
    return "minecraft:white_concrete";
  }

  function traceCenter(z) {
    return 24 + Math.round(
      2 * Math.sin(z * 0.55) + Math.sin(z * 0.19)
    );
  }

  function foamBlob(cx, cz, rx, rz) {
    for (let dx = -rx; dx <= rx; dx++) {
      for (let dz = -rz; dz <= rz; dz++) {
        const ex = dx / rx;
        const ez = dz / rz;

        if (ex * ex + ez * ez <= 1) {
          groundPatch(
            cx + dx,
            cz + dz,
            foamMaterial(cx + dx, cz + dz)
          );
        }
      }
    }
  }

  function tentacleMaterial(x, y, z, phase) {
    const n = (x * 7 + y * 11 + z * 5 + phase * 17) % 19;

    if (n === 0 || n === 1) {
      return "minecraft:prismarine";
    }
    if (n === 2) {
      return "minecraft:cyan_concrete";
    }
    return "minecraft:dark_prismarine";
  }

  function tentacle(points, radii, phase) {
    for (let seg = 0; seg < points.length - 1; seg++) {
      const a = points[seg];
      const b = points[seg + 1];

      for (let step = 0; step <= 8; step++) {
        const t = step / 8;
        const px = a[0] + (b[0] - a[0]) * t;
        const pz = a[2] + (b[2] - a[2]) * t;
        const rawY = a[1] + (b[1] - a[1]) * t;
        const r = radii[seg] + (radii[seg + 1] - radii[seg]) * t;
        const ry = Math.max(1.2, r * 0.7);

        const gx = Math.round(px);
        const gz = Math.round(pz);
        const g = terrainY(gx, gz);

        let py = Math.max(
          rawY,
          g + Math.max(1, Math.ceil(ry * 0.55))
        );

        if (py > H - 2) {
          py = H - 2;
        }

        const foot = Math.max(0, Math.floor(py - ry * 0.9));

        for (let y = 0; y <= foot; y++) {
          put(gx, y, gz, "minecraft:deepslate");
        }

        addEllipsoid(
          px,
          py,
          pz,
          r,
          ry,
          r,
          function (x, y, z) {
            return tentacleMaterial(x, y, z, phase);
          }
        );

        if (r > 1.35 && (seg * 7 + step + phase) % 5 === 0) {
          put(
            Math.round(px),
            Math.round(py + ry * 0.58),
            Math.round(pz),
            "minecraft:light_blue_concrete"
          );
        }
      }
    }
  }

  for (let x = 9; x <= 39; x++) {
    for (let z = 18; z <= 44; z++) {
      const dx = (x - 24) / 15;
      const dz = (z - 31) / 13;

      if (dx * dx + dz * dz <= 1) {
        const g = terrainY(x, z);
        const top = 2 + g;

        for (let y = 0; y <= top; y++) {
          let block = "minecraft:deepslate";

          if (y >= 2) {
            block = "minecraft:dark_prismarine";
          }
          if (y === top && (x * 3 + z * 5) % 5 === 0) {
            block = "minecraft:prismarine_bricks";
          }

          put(x, y, z, block);
        }
      }
    }
  }

  for (let y = 2; y <= 28; y++) {
    let rx;
    let rz;
    let cz;

    if (y <= 8) {
      const t = (y - 2) / 6;
      rx = 12 - 2 * t;
      rz = 9.5 - 0.8 * t;
      cz = 30.5 - 0.8 * t;
    } else if (y <= 18) {
      const t = (y - 8) / 10;
      rx = 10 - 1.8 * t;
      rz = 8.7 - 1.2 * t;
      cz = 29.7 - 2 * t;
    } else {
      const t = (y - 18) / 10;
      rx = 8.2 - 1.1 * t;
      rz = 7.5 - 1.2 * t;
      cz = 27.7 - 1.8 * t;
    }

    for (let x = Math.floor(24 - rx); x <= Math.ceil(24 + rx); x++) {
      for (let z = Math.floor(cz - rz); z <= Math.ceil(cz + rz); z++) {
        const dx = (x - 24) / rx;
        const dz = (z - cz) / rz;

        if (dx * dx + dz * dz <= 1) {
          put(x, y, z, wetMaterial(x, y, z, 0));
        }
      }
    }
  }

  addEllipsoid(
    24,
    23,
    22.5,
    8.8,
    7.4,
    7.5,
    function (x, y, z) {
      return wetMaterial(x, y, z, 11);
    }
  );

  addEllipsoid(
    24,
    18.5,
    18.5,
    8.5,
    3.1,
    6,
    function (x, y, z) {
      return jawMaterial(x, y, z);
    }
  );

  for (let x = 18; x <= 30; x++) {
    put(x, 18, 13, "minecraft:black_concrete");
    put(x, 19, 13, "minecraft:black_concrete");
  }

  for (const x of [20, 24, 28]) {
    put(x, 18, 12, "minecraft:calcite");
    put(x, 19, 12, "minecraft:calcite");
  }

  for (const side of [-1, 1]) {
    const length = 12;

    for (let d = 0; d <= length; d++) {
      const t = d / length;
      const x = 24 + side * (7 + d);
      const zc = 29 - Math.round(4 * t);
      const halfZ = Math.max(1, Math.round(4 - 3 * t));
      const yLow = 12 + Math.floor(3 * t);
      const yHigh = 17 - Math.floor(t);

      for (let y = yLow; y <= yHigh; y++) {
        for (let z = zc - halfZ; z <= zc + halfZ; z++) {
          const n = (d * 5 + y * 3 + z * 7 + side * 11 + 50) % 13;
          let block = "minecraft:dark_prismarine";

          if (n === 0 || n === 1) {
            block = "minecraft:cyan_concrete";
          }
          if (n === 2) {
            block = "minecraft:blue_concrete";
          }

          put(x, y, z, block);
        }
      }
    }
  }

  for (let y = 24; y <= 31; y++) {
    const t = (y - 24) / 7;
    const halfX = Math.max(1, Math.round(4 - 3 * t));
    const zc = 30 + Math.round(4 * t);
    const halfZ = y < 28 ? 2 : 1;

    for (let x = 24 - halfX; x <= 24 + halfX; x++) {
      for (let z = zc - halfZ; z <= zc + halfZ; z++) {
        const n = (x * 5 + y * 3 + z * 7) % 12;
        let block = "minecraft:dark_prismarine";

        if (n === 0 || n === 1) {
          block = "minecraft:cyan_concrete";
        }
        if (n === 2) {
          block = "minecraft:prismarine";
        }

        put(x, y, z, block);
      }
    }
  }

  for (let z = 1; z <= 27; z++) {
    const t = (z - 1) / 26;
    const width = 1 + Math.floor(3 * t);
    const cx = traceCenter(z);

    for (let dx = -width; dx <= width; dx++) {
      groundPatch(
        cx + dx,
        z,
        foamMaterial(cx + dx, z)
      );
    }
  }

  foamBlob(traceCenter(25), 25, 5, 2);
  foamBlob(traceCenter(19), 19, 4, 2);
  foamBlob(traceCenter(10), 10, 3, 1);

  tentacle(
    [
      [18, 5, 27],
      [17, 4, 23],
      [19, 3, 19],
      [16, 2.3, 15],
      [18, 1.2, 10],
      [14, 1, 5]
    ],
    [3.4, 3.1, 2.7, 2.2, 1.6, 1],
    1
  );

  tentacle(
    [
      [14, 5, 30],
      [11, 4, 26],
      [9, 3, 22],
      [7, 2, 18],
      [8, 1.3, 13],
      [5, 1, 8]
    ],
    [3.2, 2.8, 2.3, 1.9, 1.5, 1],
    2
  );

  tentacle(
    [
      [31, 5, 29],
      [35, 4, 25],
      [37, 3, 21],
      [35, 2, 17],
      [38, 1.2, 12],
      [42, 1, 6]
    ],
    [3.3, 2.9, 2.4, 1.9, 1.5, 1],
    3
  );

  tentacle(
    [
      [24, 4, 25],
      [25, 3.5, 21],
      [24, 2.8, 17],
      [26, 2, 13],
      [24, 1.4, 9],
      [27, 1, 4]
    ],
    [3.5, 3, 2.6, 2, 1.5, 1],
    4
  );

  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const gx = 24 + side * (5 + i);
      const gz = 24 + i;

      for (let y = 18 + i; y <= 23 + i; y++) {
        put(
          gx,
          y,
          gz,
          i === 1 ? "minecraft:cyan_concrete" : "minecraft:prismarine"
        );
      }
    }
  }

  for (let dx = -4; dx <= 4; dx++) {
    for (let dy = -4; dy <= 4; dy++) {
      if (Math.abs(dx) === 4 || Math.abs(dy) === 4) {
        put(24 + dx, 23 + dy, 17, "minecraft:black_concrete");
      }
    }
  }

  for (let dx = -3; dx <= 3; dx++) {
    for (let dy = -3; dy <= 3; dy++) {
      put(24 + dx, 23 + dy, 17, "minecraft:sea_lantern");
    }
  }

  for (let dx = -2; dx <= 2; dx++) {
    for (let dy = -2; dy <= 2; dy++) {
      put(24 + dx, 23 + dy, 16, "minecraft:yellow_concrete");
    }
  }

  for (let y = 21; y <= 25; y++) {
    put(24, y, 15, "minecraft:black_concrete");
  }

  put(22, 25, 15, "minecraft:white_concrete");

  const edgeAnchorX = traceCenter(1);

  return {
    name: "Leviathan of the Broken Quay",
    seatY: 0,
    anchors: {
      eye: [24, 23, 15],
      waterline: [24, 2, 31],
      quay: [edgeAnchorX, 0, 1],
      dorsal_fin: [24, 31, 34],
      left_fin: [5, 16, 25],
      right_fin: [43, 16, 25]
    }
  };
}

invading_sea_monster.source:
export const envelope = [17, 20, 17];

export default function build(api) {
  const W = api.size[0];
  const H = api.size[1];
  const D = api.size[2];
  const index = api.instance.index;
  const count = api.instance.count;
  const centerX = Math.floor(W / 2);
  const centerZ = Math.floor(D / 2);

  const randomValues = [];
  for (let n = 0; n < 16; n += 1) {
    randomValues.push(api.random());
  }

  const records = [];
  const lookup = new Map();

  function voxelKey(x, y, z) {
    return x + "," + y + "," + z;
  }

  function mod(n, m) {
    const q = n % m;
    return q < 0 ? q + m : q;
  }

  function worldXZ(u, v) {
    const direction = mod(index + Math.floor(randomValues[1] * 4), 4);

    if (direction === 0) {
      return [centerX + u, centerZ + v];
    }
    if (direction === 1) {
      return [centerX + v, centerZ - u];
    }
    if (direction === 2) {
      return [centerX - u, centerZ - v];
    }
    return [centerX - v, centerZ + u];
  }

  function clampInt(n, lo, hi) {
    const q = Math.round(n);
    if (q < lo) {
      return lo;
    }
    if (q > hi) {
      return hi;
    }
    return q;
  }

  function raw(u, v, y, block) {
    const p = worldXZ(u, v);

    if (
      p[0] < 0 ||
      p[0] >= W ||
      p[1] < 0 ||
      p[1] >= D ||
      y < 0 ||
      y >= H
    ) {
      return;
    }

    const key = voxelKey(p[0], y, p[1]);
    const oldIndex = lookup.get(key);

    if (oldIndex === undefined) {
      lookup.set(key, records.length);
      records.push({
        x: p[0],
        y: y,
        z: p[1],
        block: block
      });
    } else {
      records[oldIndex].block = block;
    }
  }

  function terrainLevel(u, v) {
    const p = worldXZ(u, v);
    let h = Math.floor(api.heightAt(p[0], p[1]));

    if (h !== h || h < 0) {
      h = 0;
    }
    if (h >= H) {
      h = H - 1;
    }

    return h;
  }

  let lift = terrainLevel(0, 0);
  if (lift > 2) {
    lift = 2;
  }

  function put(u, v, y, block) {
    raw(u, v, y + lift, block);
  }

  const foundationBlock = "minecraft:stone";

  const pavingPalette = [
    "minecraft:stone_bricks",
    "minecraft:cobblestone",
    "minecraft:cracked_stone_bricks",
    "minecraft:deepslate",
    "minecraft:polished_blackstone"
  ];

  const rubblePalette = [
    "minecraft:cobblestone",
    "minecraft:cracked_stone_bricks",
    "minecraft:stone",
    "minecraft:deepslate",
    "minecraft:polished_blackstone"
  ];

  const craterPalette = [
    "minecraft:polished_blackstone",
    "minecraft:deepslate_tiles",
    "minecraft:cracked_stone_bricks",
    "minecraft:dark_prismarine"
  ];

  const wetHide = [
    "minecraft:dark_prismarine",
    "minecraft:prismarine",
    "minecraft:prismarine_bricks",
    "minecraft:deepslate_tiles",
    "minecraft:warped_wart_block",
    "minecraft:oxidized_copper"
  ];

  const shellPalette = [
    "minecraft:polished_deepslate",
    "minecraft:deepslate_bricks",
    "minecraft:dark_prismarine",
    "minecraft:prismarine_bricks",
    "minecraft:oxidized_copper",
    "minecraft:polished_blackstone"
  ];

  const tentaclePalette = [
    "minecraft:dark_prismarine",
    "minecraft:warped_wart_block",
    "minecraft:blue_concrete",
    "minecraft:cyan_concrete",
    "minecraft:deepslate_tiles",
    "minecraft:prismarine"
  ];

  const finPalette = [
    "minecraft:prismarine_bricks",
    "minecraft:dark_prismarine",
    "minecraft:deepslate_bricks",
    "minecraft:oxidized_copper",
    "minecraft:blue_concrete"
  ];

  const tailPalette = [
    "minecraft:dark_prismarine",
    "minecraft:prismarine",
    "minecraft:deepslate_tiles",
    "minecraft:warped_wart_block"
  ];

  const sprayPalette = [
    "minecraft:cyan_concrete",
    "minecraft:light_blue_concrete",
    "minecraft:prismarine",
    "minecraft:blue_concrete"
  ];

  const impactRadius =
    5 + mod(index + count + Math.floor(randomValues[0] * 3), 3);
  const impactDepth = Math.max(4, impactRadius - 1);

  const bodyU =
    randomValues[2] < 0.3
      ? -1
      : randomValues[2] > 0.77
        ? 1
        : 0;

  const bodyV = randomValues[3] > 0.75 ? 1 : 0;
  const bodyRU = 5 + (randomValues[4] > 0.65 ? 1 : 0);
  const bodyRV = 4 + (mod(index + count, 5) === 0 ? 1 : 0);
  const bodyRY = 6.5 + (randomValues[5] > 0.75 ? 0.5 : 0);
  const tilePhase = Math.floor(randomValues[6] * 100);
  const skinSalt = Math.floor(randomValues[6] * 43);

  function footColumn(u, v) {
    const g = terrainLevel(u, v);
    const top = Math.max(g, lift);

    for (let y = 0; y <= top; y += 1) {
      raw(u, v, y, foundationBlock);
    }

    return [g, top];
  }

  for (let u = -impactRadius; u <= impactRadius; u += 1) {
    for (let v = -impactDepth; v <= impactDepth; v += 1) {
      const du = u / impactRadius;
      const dv = v / impactDepth;

      if (du * du + dv * dv <= 1.02) {
        const levels = footColumn(u, v);
        const tile =
          pavingPalette[
            mod(u * 11 + v * 7 + index + tilePhase, pavingPalette.length)
          ];

        raw(u, v, levels[1], tile);
      }
    }
  }

  function roundedBlob(u0, v0, y0, ru, rv, ry, material) {
    const yMin = Math.ceil(y0 - ry);
    const yMax = Math.floor(y0 + ry);

    for (let y = yMin; y <= yMax; y += 1) {
      for (let v = Math.floor(v0 - rv); v <= Math.ceil(v0 + rv); v += 1) {
        for (let u = Math.floor(u0 - ru); u <= Math.ceil(u0 + ru); u += 1) {
          const dx = (u - u0) / ru;
          const dz = (v - v0) / rv;
          const dy = (y - y0) / ry;
          const q = dx * dx + dz * dz + dy * dy;

          if (q <= 1.0001) {
            let block = material;
            if (typeof material === "function") {
              block = material(u, v, y, q);
            }
            put(u, v, y, block);
          }
        }
      }
    }
  }

  function lump(u0, v0, y0, radius, halfY, material) {
    const rr = Math.max(1, Math.floor(radius));
    const yMin = Math.floor(y0 - halfY);
    const yMax = Math.ceil(y0 + halfY);

    for (let v = u0 - rr; v <= u0 + rr; v += 1) {
      for (let u = v0 - rr; u <= v0 + rr; u += 1) {
        const du = u - v0;
        const dv = v - u0;

        if (du * du + dv * dv <= rr * rr + 1) {
          for (let y = yMin; y <= yMax; y += 1) {
            let block = material;
            if (typeof material === "function") {
              block = material(u, v, y);
            }
            put(u, v, y, block);
          }
        }
      }
    }
  }

  function hideBlock(u, v, y, q) {
    const n = mod(
      u * 13 + v * 7 + y * 5 + skinSalt + index,
      wetHide.length
    );

    if (
      q > 0.58 ||
      mod(u * 5 + v * 3 + y + skinSalt, 7) === 0
    ) {
      return shellPalette[mod(n + index, shellPalette.length)];
    }

    return wetHide[n];
  }

  function lowerBlock(u, v, y, q) {
    const n = mod(u * 9 + v * 5 + y * 3 + index, wetHide.length);

    if (q > 0.35) {
      return shellPalette[mod(n + 2, shellPalette.length)];
    }

    return wetHide[n];
  }

  function headBlock(u, v, y, q) {
    const n = mod(u * 7 + v * 11 + y * 3 + index, shellPalette.length);

    if (
      q > 0.42 ||
      mod(u + v + y + index, 5) === 0
    ) {
      return shellPalette[n];
    }

    return wetHide[mod(n + 1, wetHide.length)];
  }

  roundedBlob(
    bodyU,
    bodyV,
    2.1,
    4.2,
    3.1,
    2.2,
    lowerBlock
  );

  roundedBlob(
    bodyU,
    bodyV,
    8.5,
    bodyRU,
    bodyRV,
    bodyRY,
    hideBlock
  );

  roundedBlob(
    bodyU,
    bodyV + 1,
    6.2,
    4.1,
    3.2,
    4.1,
    hideBlock
  );

  for (let y = 0; y <= 15; y += 1) {
    put(
      bodyU,
      bodyV,
      y,
      shellPalette[mod(y + index, shellPalette.length)]
    );
  }

  const headU =
    bodyU +
    (randomValues[7] < 0.22
      ? -1
      : randomValues[7] > 0.86
        ? 1
        : 0);

  const headV = bodyV + 2;
  const headY = 11.5 + (randomValues[8] > 0.55 ? 0.5 : 0);
  const headRU = 3.5 + (mod(index + count, 4) === 1 ? 0.5 : 0);
  const headRY = 3.4 + (randomValues[8] > 0.75 ? 0.4 : 0);
  const jawForward = randomValues[9] > 0.48 ? 1 : 0;
  const snoutV = bodyV + 3 + jawForward;
  const mouthV = clampInt(snoutV + 2, -8, 7);

  roundedBlob(
    headU,
    headV,
    headY,
    headRU,
    3.5,
    headRY,
    headBlock
  );

  roundedBlob(
    headU,
    snoutV,
    10.7 + (index / Math.max(1, count - 1) > 0.65 ? 0.3 : 0),
    3.0,
    2.8,
    2.4,
    headBlock
  );

  function linkLumps(from, to, radius, halfY, material) {
    let u = from[0];
    let v = from[1];
    let y = from[2];

    while (u !== to[0] || v !== to[1] || y !== to[2]) {
      if (u !== to[0]) {
        u += to[0] > u ? 1 : -1;
      } else if (v !== to[1]) {
        v += to[1] > v ? 1 : -1;
      } else {
        y += to[2] > y ? 1 : -1;
      }

      lump(u, v, y, radius, halfY, material);
    }
  }

  function addTail() {
    const tailLength =
      5 + mod(index + Math.floor(randomValues[10] * 5), 2);
    const phase = Math.floor(randomValues[10] * 8);
    let previous = [bodyU, bodyV - 2, 4];

    lump(
      previous[0],
      previous[1],
      previous[2],
      2,
      1,
      tailPalette[mod(index + phase, tailPalette.length)]
    );

    for (let t = 1; t <= tailLength; t += 1) {
      const target = [
        clampInt(
          bodyU + Math.round(Math.sin((t + phase) * 0.8)),
          -8,
          8
        ),
        clampInt(bodyV - 2 - t, -8, 8),
        Math.max(1, 4 - Math.floor((t + 1) / 2))
      ];

      const material =
        tailPalette[
          mod(index + phase + t, tailPalette.length)
        ];

      linkLumps(previous, target, 1, 1, material);
      previous = target;
    }
  }

  function addTentacle(startU, startV, du, dv, length, phase, kind) {
    let previous = null;

    for (let t = 0; t <= length; t += 1) {
      const curve = Math.round(
        Math.sin((t + phase) * 0.72) * (kind === 2 ? 0.6 : 1)
      );

      let u = startU + du * t;
      let v = startV + dv * t;

      if (du === 0) {
        u += curve;
      } else if (dv === 0) {
        v += curve;
      } else {
        u += curve;
      }

      u = clampInt(u, -8, 8);
      v = clampInt(v, -8, 8);

      const y = Math.max(
        0,
        2 - Math.floor((t + mod(phase, 2)) / 2)
      );

      const target = [u, v, y];
      const material =
        tentaclePalette[
          mod(index + kind * 3 + phase + t, tentaclePalette.length)
        ];

      footColumn(u, v);

      if (previous === null) {
        lump(u, v, y, t < 2 ? 2 : 1, 1, material);
      } else {
        linkLumps(previous, target, t < 2 ? 2 : 1, 1, material);
      }

      previous = target;
    }
  }

  addTail();

  const waveStage = index / Math.max(1, count - 1);

  const frontLength =
    5 +
    mod(
      index +
        count +
        Math.floor(randomValues[11] * 4) +
        Math.floor(waveStage * 3),
      3
    );

  const sideLength =
    4 + mod(index + Math.floor(randomValues[12] * 5), 3);

  const rearLength =
    5 + mod(index + count + Math.floor(randomValues[13] * 3), 2);

  const tentaclePhase = Math.floor(randomValues[14] * 7);

  addTentacle(
    bodyU - 2,
    bodyV + 1,
    0,
    1,
    frontLength,
    tentaclePhase,
    0
  );

  addTentacle(
    bodyU + 2,
    bodyV + 1,
    0,
    1,
    Math.max(4, frontLength - 1),
    tentaclePhase + 2,
    1
  );

  addTentacle(
    bodyU - 3,
    bodyV,
    -1,
    0,
    sideLength,
    tentaclePhase + 1,
    2
  );

  addTentacle(
    bodyU + 3,
    bodyV,
    1,
    0,
    sideLength,
    tentaclePhase + 3,
    3
  );

  addTentacle(
    bodyU,
    bodyV - 2,
    0,
    -1,
    rearLength,
    tentaclePhase + 4,
    4
  );

  if (
    mod(index + count + Math.floor(randomValues[15] * 8), 4) !== 0
  ) {
    addTentacle(
      bodyU - 1,
      bodyV + 1,
      -1,
      1,
      4 + mod(index + count, 2),
      tentaclePhase + 5,
      5
    );
  }

  const finSlope = 0.28 + randomValues[11] * 0.18;
  let lastBackV = bodyV - 3;

  for (let y = 8; y <= 17; y += 1) {
    const backV =
      bodyV - 3 - Math.floor((y - 8) * finSlope);
    const half = y < 13 ? 1 : 0;

    for (let u = bodyU - half; u <= bodyU + half; u += 1) {
      put(
        u,
        backV,
        y,
        finPalette[
          mod(
            index +
              y +
              u +
              Math.floor(randomValues[10] * 10),
            finPalette.length
          )
        ]
      );
    }

    if (y > 8) {
      put(
        bodyU,
        lastBackV,
        y,
        finPalette[
          mod(index + y + 3, finPalette.length)
        ]
      );
    }

    lastBackV = backV;
  }

  function addSideFin(side, enabled, style) {
    if (!enabled) {
      return;
    }

    const maxQ =
      3 + mod(index + style + Math.floor(randomValues[12] * 3), 2);

    let previousFinU = bodyU + side * 4;

    for (let q = 0; q <= maxQ; q += 1) {
      const finU = clampInt(
        bodyU + side * (4 + q),
        -8,
        8
      );

      const finY = 8 - Math.floor(q / 2);
      const vMax = 3 - Math.floor(q / 2);

      for (let y = finY; y <= finY + 1; y += 1) {
        for (let v = -1; v <= vMax; v += 1) {
          put(
            finU,
            bodyV + v,
            y,
            finPalette[
              mod(index + style * 5 + q + y + v, finPalette.length)
            ]
          );

          if (q > 0) {
            put(
              previousFinU,
              bodyV + v,
              y,
              finPalette[
                mod(index + style * 5 + q + y + v + 1, finPalette.length)
              ]
            );
          }
        }
      }

      previousFinU = finU;
    }
  }

  let leftFin =
    mod(index + Math.floor(randomValues[12] * 9), 5) !== 0;

  let rightFin =
    mod(index + 2 + Math.floor(randomValues[12] * 11), 6) !== 1;

  if (!leftFin && !rightFin) {
    rightFin = true;
  }

  addSideFin(-1, leftFin, 1);
  addSideFin(1, rightFin, 2);

  const damageLevel =
    mod(index + count + Math.floor(randomValues[13] * 8), 4);

  for (let row = 0; row < 5; row += 1) {
    const y = 5 + row * 2;

    for (let side = -1; side <= 1; side += 2) {
      if (
        mod(
          row + (side < 0 ? 0 : 1) + damageLevel,
          5
        ) !== 0
      ) {
        put(
          bodyU + side * 4,
          bodyV + (row % 2),
          y,
          shellPalette[
            mod(row + side + index + damageLevel, shellPalette.length)
          ]
        );
      }
    }
  }

  for (let n = 0; n < 6; n += 1) {
    if (mod(n + damageLevel, 6) !== 2) {
      put(
        bodyU + (n % 3) - 1,
        bodyV - 4,
        5 + n,
        shellPalette[
          mod(n + index + damageLevel + 2, shellPalette.length)
        ]
      );
    }
  }

  const mouthWidth =
    2 + mod(index + Math.floor(randomValues[9] * 3), 2);

  for (let y = 9; y <= 13; y += 1) {
    for (let u = -mouthWidth; u <= mouthWidth; u += 1) {
      put(
        headU + u,
        mouthV,
        y,
        "minecraft:polished_blackstone"
      );
    }
  }

  const toothV = clampInt(mouthV + 1, -8, 8);

  for (let u = -mouthWidth + 1; u <= mouthWidth - 1; u += 2) {
    put(headU + u, toothV, 9, "minecraft:calcite");
    put(headU + u, toothV, 13, "minecraft:calcite");
  }

  const eyeY = Math.floor(headY + 1);

  for (let side = -1; side <= 1; side += 2) {
    const eyeU = headU + side * 2;

    put(
      eyeU,
      headV + 3,
      eyeY,
      "minecraft:yellow_concrete"
    );

    put(
      eyeU,
      headV + 2,
      eyeY + 1,
      "minecraft:polished_deepslate"
    );
  }

  const serialU = [-2, 2, -2, 2, 0];
  const serialV = [0, 0, 1, 1, 0];
  const serialY = [8, 8, 10, 10, 12];

  for (let bit = 0; bit < 5; bit += 1) {
    if ((index & (1 << bit)) !== 0) {
      put(
        bodyU + serialU[bit],
        bodyV + serialV[bit],
        serialY[bit],
        "minecraft:crying_obsidian"
      );
    }
  }

  function groundPatch(u, v, tile) {
    const uu = clampInt(u, -8, 8);
    const vv = clampInt(v, -8, 8);
    const g = terrainLevel(uu, vv);

    for (let y = 0; y <= g; y += 1) {
      raw(uu, vv, y, foundationBlock);
    }

    raw(uu, vv, g, tile);
  }

  function lineTo(targetU, targetV, tile) {
    let u = 0;
    let v = 0;

    groundPatch(0, 0, tile);

    while (u !== targetU || v !== targetV) {
      if (u !== targetU) {
        u += targetU > u ? 1 : -1;
      } else {
        v += targetV > v ? 1 : -1;
      }

      groundPatch(u, v, tile);
    }
  }

  for (let u = -3; u <= 3; u += 1) {
    for (let v = -3; v <= 3; v += 1) {
      if ((u * u) / 10 + (v * v) / 8 <= 1.15) {
        groundPatch(
          u,
          v,
          craterPalette[
            mod(u * 5 + v * 9 + damageLevel, craterPalette.length)
          ]
        );
      }
    }
  }

  const spokeCount =
    9 + mod(index + Math.floor(randomValues[0] * 4), 4);
  const spokeRadius = impactRadius - 1;
  const spokeDepth = Math.max(3, impactDepth - 1);
  const spokePhase = randomValues[1] * Math.PI * 2;

  for (let s = 0; s < spokeCount; s += 1) {
    if (mod(s + damageLevel + index, 4) !== 0) {
      const angle =
        spokePhase + (s * Math.PI * 2) / spokeCount;

      const targetU = clampInt(
        Math.cos(angle) * spokeRadius,
        -8,
        8
      );

      const targetV = clampInt(
        Math.sin(angle) * spokeDepth,
        -8,
        8
      );

      const tile =
        rubblePalette[
          mod(s + index + damageLevel, rubblePalette.length)
        ];

      lineTo(targetU, targetV, tile);

      for (let a = -1; a <= 1; a += 1) {
        for (let b = -1; b <= 1; b += 1) {
          groundPatch(
            targetU + a,
            targetV + b,
            rubblePalette[
              mod(
                s * 3 + a * 7 + b * 11 + index,
                rubblePalette.length
              )
            ]
          );
        }
      }
    }
  }

  function addSpray(u, v, heightRequest, style) {
    const uu = clampInt(u, -8, 8);
    const vv = clampInt(v, -8, 8);

    lineTo(
      uu,
      vv,
      rubblePalette[mod(style + index, rubblePalette.length)]
    );

    const g = terrainLevel(uu, vv);
    const actualHeight = Math.min(
      heightRequest,
      Math.max(0, H - 1 - g)
    );

    const top = g + actualHeight;
    const sprayBlock =
      sprayPalette[mod(style + index, sprayPalette.length)];

    for (let y = g; y <= top; y += 1) {
      raw(uu, vv, y, sprayBlock);
    }

    if (actualHeight >= 2) {
      const branchY = top - 1;
      const side = mod(style + index, 2) === 0 ? 1 : -1;
      const branchLength = 1 + mod(style + index, 2);

      for (let q = 1; q <= branchLength; q += 1) {
        const branchU = clampInt(uu + side * q, -8, 8);
        const branchBlock =
          sprayPalette[
            mod(style + q + index + 1, sprayPalette.length)
          ];

        raw(branchU, vv, branchY, branchBlock);

        if (branchY + 1 <= top) {
          raw(branchU, vv, branchY + 1, branchBlock);
        }
      }
    }
  }

  const sprayCount =
    2 + mod(index + Math.floor(randomValues[15] * 5), 2);
  const sprayRadius = Math.max(3, impactRadius - 2);
  const sprayDepth = Math.max(2, impactDepth - 2);
  const sprayPhase = randomValues[1] * Math.PI * 2 + 0.8;

  for (let s = 0; s < sprayCount; s += 1) {
    const angle =
      sprayPhase + (s * Math.PI * 2) / sprayCount;

    const sprayU = Math.round(
      Math.cos(angle) * sprayRadius
    );

    const sprayV = Math.round(
      Math.sin(angle) * sprayDepth
    );

    const sprayHeight =
      3 +
      mod(
        index +
          count +
          s +
          Math.floor(randomValues[4] * 5),
        4
      );

    addSpray(sprayU, sprayV, sprayHeight, s);
  }

  const visited = new Uint8Array(records.length);
  let bestComponent = [];

  for (let start = 0; start < records.length; start += 1) {
    if (visited[start] !== 0) {
      continue;
    }

    const stack = [start];
    const component = [];
    visited[start] = 1;

    while (stack.length > 0) {
      const current = stack.pop();
      const record = records[current];
      component.push(current);

      const neighbors = [
        [record.x + 1, record.y, record.z],
        [record.x - 1, record.y, record.z],
        [record.x, record.y + 1, record.z],
        [record.x, record.y - 1, record.z],
        [record.x, record.y, record.z + 1],
        [record.x, record.y, record.z - 1]
      ];

      for (let n = 0; n < neighbors.length; n += 1) {
        const neighborIndex = lookup.get(
          voxelKey(
            neighbors[n][0],
            neighbors[n][1],
            neighbors[n][2]
          )
        );

        if (
          neighborIndex !== undefined &&
          visited[neighborIndex] === 0
        ) {
          visited[neighborIndex] = 1;
          stack.push(neighborIndex);
        }
      }
    }

    if (component.length > bestComponent.length) {
      bestComponent = component;
    }
  }

  const keep = new Uint8Array(records.length);

  for (let n = 0; n < bestComponent.length; n += 1) {
    keep[bestComponent[n]] = 1;
  }

  for (let n = 0; n < records.length; n += 1) {
    if (keep[n] !== 0) {
      const record = records[n];
      api.set(record.x, record.y, record.z, record.block);
    }
  }

  const impactXZ = worldXZ(0, 0);
  const mawXZ = worldXZ(headU, mouthV);
  const crestXZ = worldXZ(bodyU, bodyV - 5);

  const frontAnchorV = clampInt(
    bodyV + 1 + frontLength,
    -8,
    8
  );

  const advanceXZ = worldXZ(bodyU, frontAnchorV);

  return {
    name: "Invading Sea Monster",
    seatY: 0,
    anchors: {
      impact: [
        impactXZ[0],
        terrainLevel(0, 0),
        impactXZ[1]
      ],
      maw: [
        mawXZ[0],
        11 + lift,
        mawXZ[1]
      ],
      crest: [
        crestXZ[0],
        17 + lift,
        crestXZ[1]
      ],
      advance: [
        advanceXZ[0],
        lift,
        advanceXZ[1]
      ]
    }
  };
}
